#!/usr/bin/env bash
# Creates the annotated release tag vX.Y.Z on HEAD (docs/release.md item 7). The message holds
# the release's notes, generated by git-cliff from the Conventional Commits since the last
# release tag, followed by the docs checklist results (item 6) from <results-file>.
# Never pushes. Usage: release-tag.sh <git-cliff> <X.Y.Z> <results-file>
set -euo pipefail

# Keep identical to tag_pattern in cliff.toml.
RELEASE_TAG_RE='^v[0-9]+\.[0-9]+\.[0-9]+$'

cliff="${1:?usage: release-tag.sh <git-cliff> <X.Y.Z> <results-file>}"
version="${2:-}"
results="${3:-}"

die() {
  echo "error: $1" >&2
  shift
  for hint in "$@"; do echo "  hint: $hint" >&2; done
  exit 1
}

[[ -n "$version" && -n "$results" ]] ||
  die "release:tag needs the version and the file holding item 6's results" "task release:tag -- 0.1.0 checks.md"
version="${version#v}"
[[ "v$version" =~ $RELEASE_TAG_RE ]] ||
  die "version \"$version\" is not X.Y.Z" "task release:tag -- 0.1.0 $results"
[[ -s "$results" ]] ||
  die "results file \"$results\" is missing or empty; it holds item 6's results (docs/release.md)"
[[ -z "$(git status --porcelain)" ]] ||
  die "the work tree is not clean; the tag goes on the commit every checklist item passed on" "git status"
! git rev-parse -q --verify "refs/tags/v$version" >/dev/null ||
  die "tag v$version already exists" "git show v$version"

last="$(git tag --merged HEAD --list 'v*' --sort=-v:refname | grep -E -m1 "$RELEASE_TAG_RE" || true)"
if [[ -n "$last" ]]; then
  newest="$(printf '%s\n%s\n' "${last#v}" "$version" | sort -V | tail -n1)"
  [[ "$newest" == "$version" && "${last#v}" != "$version" ]] ||
    die "v$version is not after the last release, $last"
fi

notes="$("$cliff" --config cliff.toml --unreleased --tag "v$version" --strip all | sed "/./,\$!d")"
grep -q '^- ' <<<"$notes" ||
  die "no Conventional Commit since ${last:-the start of the history}; there is nothing to release" "task release:notes"

msg="$(mktemp)"
trap 'rm -f "$msg"' EXIT
{
  printf 'lola v%s\n\n%s\n\n## Release checks\n\n' "$version" "$notes"
  cat "$results"
} >"$msg"

git tag -a --cleanup=verbatim "v$version" -F "$msg"
echo "✓ tagged v$version on $(git rev-parse --short HEAD)"
echo "  review: git show v$version"
echo "  publish when ready: git push origin v$version"
